-- Compare refresh part 5/5 — choose_a/b=text(json), faq=jsonb

-- continue-dev-vs-github-copilot
UPDATE comparisons SET choose_a='["✅ You want the open-source IDE extensions (VS Code, JetBrains) so you can connect any LLM — Claude Opus 4.8, GPT-5.5, or local Ollama models — without provider lock-in", "✅ You prioritize privacy and want to run local models so your code never leaves your machine", "✅ You want a self-hosted, fully controllable coding assistant with no subscription fee — you pay only for the model API you connect", "✅ You build custom, hackable AI coding workflows and want an extensible assistant you configure yourself"]', choose_b='["✅ You want the most reliable, battle-tested AI coding assistant with the largest ecosystem and active development", "✅ You use VS Code, JetBrains, or Visual Studio and want seamless, first-party IDE integration", "✅ Your team is on GitHub and wants AI built into PRs, issues, and code review", "✅ You need a free tier to start ($0/mo) and a simple upgrade path to Pro at $10/mo with model selection", "✅ You need enterprise features: SSO, audit logs, IP indemnity, and policy controls"]', faq='[{"q": "Is Continue.dev still an independent product?", "a": "No. Continue was acquired by Cursor (Anysphere) around mid-June 2026, and the standalone product is being wound down. The remaining offering is the open-source IDE extensions for VS Code and JetBrains, with v2.0.0 as the final release. You can still use these open-source extensions to connect your own LLMs."}, {"q": "Is Continue.dev free?", "a": "The open-source IDE extensions are free. There is no Continue subscription fee — you pay only for the model API you connect (for example Claude Opus 4.8 or GPT-5.5), or nothing at all if you run local models via Ollama."}, {"q": "How much does GitHub Copilot cost?", "a": "GitHub Copilot is a multi-model platform in 2026. The Individual Free plan is $0/mo (around 2,000 completions per month with limited chat and agent use and automatic model selection). Pro is $10/mo with unlimited completions and model selection, and verified students get Copilot for free."}, {"q": "Can Continue.dev use local models?", "a": "Yes. The open-source extensions connect to Ollama or LM Studio running local models (Llama, Mistral, Qwen, and others) for completely private, offline coding assistance with no API costs."}]'::jsonb WHERE slug='continue-dev-vs-github-copilot' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вам нужны open-source расширения для IDE (VS Code, JetBrains), чтобы подключать любую LLM — Claude Opus 4.8, GPT-5.5 или локальные модели Ollama — без привязки к одному провайдеру", "✅ Для вас важна приватность, и вы хотите запускать локальные модели, чтобы код не покидал вашу машину", "✅ Вам нужен self-hosted ассистент под полным контролем без платной подписки — вы платите только за API модели, которую подключаете", "✅ Вы строите собственные гибкие AI-процессы разработки и хотите расширяемый ассистент, который настраиваете сами"]', choose_b='["✅ Вам нужен самый надёжный и проверенный AI-ассистент с крупнейшей экосистемой и активной разработкой", "✅ Вы работаете в VS Code, JetBrains или Visual Studio и хотите бесшовную встроенную интеграцию", "✅ Ваша команда на GitHub и хочет AI прямо в PR, issues и код-ревью", "✅ Вам нужен бесплатный старт ($0/мес) и простой переход на Pro за $10/мес с выбором моделей", "✅ Вам нужны корпоративные функции: SSO, аудит-логи, IP-индемнити и политики управления"]', faq='[{"q": "Continue.dev всё ещё независимый продукт?", "a": "Нет. Continue был приобретён Cursor (Anysphere) примерно в середине июня 2026 года, и отдельный продукт сворачивается. Осталось только open-source расширение для IDE (VS Code и JetBrains) с версией v2.0.0 как финальным релизом. Вы по-прежнему можете использовать эти open-source расширения для подключения собственных LLM."}, {"q": "Continue.dev бесплатный?", "a": "Open-source расширения для IDE бесплатны. Подписки Continue нет — вы платите только за API подключаемой модели (например, Claude Opus 4.8 или GPT-5.5) или вообще ничего, если запускаете локальные модели через Ollama."}, {"q": "Сколько стоит GitHub Copilot?", "a": "В 2026 году GitHub Copilot — это мультимодельная платформа. Бесплатный план Individual стоит $0/мес (около 2 000 автодополнений в месяц с ограниченным чатом и агентом и автоматическим выбором модели). Pro стоит $10/мес с безлимитными автодополнениями и выбором моделей, а проверенные студенты получают Copilot бесплатно."}, {"q": "Может ли Continue.dev использовать локальные модели?", "a": "Да. Open-source расширения подключаются к Ollama или LM Studio с локальными моделями (Llama, Mistral, Qwen и другими) для полностью приватной офлайн-помощи в разработке без затрат на API."}]'::jsonb WHERE slug='continue-dev-vs-github-copilot' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Quieres las extensiones de IDE de código abierto (VS Code, JetBrains) para conectar cualquier LLM — Claude Opus 4.8, GPT-5.5 o modelos locales de Ollama — sin depender de un solo proveedor", "✅ Priorizas la privacidad y quieres ejecutar modelos locales para que tu código nunca salga de tu máquina", "✅ Quieres un asistente autoalojado y bajo tu control total, sin cuota de suscripción — solo pagas por la API del modelo que conectes", "✅ Creas flujos de trabajo de IA personalizados y quieres un asistente extensible que configuras tú mismo"]', choose_b='["✅ Quieres el asistente de IA más fiable y probado, con el mayor ecosistema y desarrollo activo", "✅ Usas VS Code, JetBrains o Visual Studio y quieres una integración nativa y fluida en el IDE", "✅ Tu equipo está en GitHub y quiere IA integrada en PRs, issues y revisiones de código", "✅ Necesitas un plan gratuito para empezar ($0/mes) y una ruta sencilla a Pro por $10/mes con selección de modelos", "✅ Necesitas funciones empresariales: SSO, registros de auditoría, indemnización de PI y controles de políticas"]', faq='[{"q": "¿Sigue siendo Continue.dev un producto independiente?", "a": "No. Continue fue adquirido por Cursor (Anysphere) hacia mediados de junio de 2026, y el producto independiente se está retirando. La oferta restante son las extensiones de IDE de código abierto para VS Code y JetBrains, con la v2.0.0 como versión final. Aún puedes usar estas extensiones de código abierto para conectar tus propios LLM."}, {"q": "¿Continue.dev es gratis?", "a": "Las extensiones de IDE de código abierto son gratuitas. No hay cuota de suscripción de Continue — solo pagas por la API del modelo que conectes (por ejemplo, Claude Opus 4.8 o GPT-5.5), o nada si ejecutas modelos locales con Ollama."}, {"q": "¿Cuánto cuesta GitHub Copilot?", "a": "En 2026, GitHub Copilot es una plataforma multimodelo. El plan Individual Free cuesta $0/mes (unas 2.000 finalizaciones al mes con chat y agente limitados y selección automática de modelo). Pro cuesta $10/mes con finalizaciones ilimitadas y selección de modelos, y los estudiantes verificados obtienen Copilot gratis."}, {"q": "¿Puede Continue.dev usar modelos locales?", "a": "Sí. Las extensiones de código abierto se conectan a Ollama o LM Studio con modelos locales (Llama, Mistral, Qwen y otros) para una asistencia de codificación totalmente privada y sin conexión, sin costes de API."}]'::jsonb WHERE slug='continue-dev-vs-github-copilot' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du willst die Open-Source-IDE-Erweiterungen (VS Code, JetBrains), um jedes LLM anzubinden — Claude Opus 4.8, GPT-5.5 oder lokale Ollama-Modelle — ohne Anbieterbindung", "✅ Dir ist Datenschutz wichtig und du möchtest lokale Modelle nutzen, damit dein Code deinen Rechner nie verlässt", "✅ Du willst einen selbst gehosteten, voll kontrollierbaren Assistenten ohne Abogebühr — du zahlst nur für die API des Modells, das du anbindest", "✅ Du baust eigene, anpassbare KI-Workflows und willst einen erweiterbaren Assistenten, den du selbst konfigurierst"]', choose_b='["✅ Du willst den zuverlässigsten, bewährtesten KI-Assistenten mit dem größten Ökosystem und aktiver Entwicklung", "✅ Du nutzt VS Code, JetBrains oder Visual Studio und willst eine nahtlose, native IDE-Integration", "✅ Dein Team ist auf GitHub und will KI direkt in PRs, Issues und Code-Reviews", "✅ Du brauchst einen kostenlosen Einstieg ($0/Monat) und einen einfachen Weg zu Pro für $10/Monat mit Modellauswahl", "✅ Du brauchst Enterprise-Funktionen: SSO, Audit-Logs, IP-Haftungsfreistellung und Richtlinienkontrollen"]', faq='[{"q": "Ist Continue.dev noch ein eigenständiges Produkt?", "a": "Nein. Continue wurde etwa Mitte Juni 2026 von Cursor (Anysphere) übernommen, und das eigenständige Produkt wird eingestellt. Übrig bleiben die Open-Source-IDE-Erweiterungen für VS Code und JetBrains mit v2.0.0 als finalem Release. Diese Open-Source-Erweiterungen kannst du weiterhin nutzen, um eigene LLMs anzubinden."}, {"q": "Ist Continue.dev kostenlos?", "a": "Die Open-Source-IDE-Erweiterungen sind kostenlos. Es gibt keine Continue-Abogebühr — du zahlst nur für die API des angebundenen Modells (z. B. Claude Opus 4.8 oder GPT-5.5) oder gar nichts, wenn du lokale Modelle über Ollama betreibst."}, {"q": "Was kostet GitHub Copilot?", "a": "2026 ist GitHub Copilot eine Multi-Modell-Plattform. Der Individual-Free-Plan kostet $0/Monat (rund 2.000 Vervollständigungen pro Monat mit begrenztem Chat und Agent sowie automatischer Modellauswahl). Pro kostet $10/Monat mit unbegrenzten Vervollständigungen und Modellauswahl, und verifizierte Studierende erhalten Copilot kostenlos."}, {"q": "Kann Continue.dev lokale Modelle nutzen?", "a": "Ja. Die Open-Source-Erweiterungen verbinden sich mit Ollama oder LM Studio mit lokalen Modellen (Llama, Mistral, Qwen u. a.) für vollständig private, offline-fähige Coding-Unterstützung ohne API-Kosten."}]'::jsonb WHERE slug='continue-dev-vs-github-copilot' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Вам потрібні open-source розширення для IDE (VS Code, JetBrains), щоб підключати будь-яку LLM — Claude Opus 4.8, GPT-5.5 чи локальні моделі Ollama — без прив''язки до одного провайдера", "✅ Для вас важлива приватність, і ви хочете запускати локальні моделі, щоб код не залишав вашу машину", "✅ Вам потрібен self-hosted асистент під повним контролем без платної підписки — ви платите лише за API моделі, яку підключаєте", "✅ Ви будуєте власні гнучкі AI-процеси розробки й хочете розширюваний асистент, який налаштовуєте самі"]', choose_b='["✅ Вам потрібен найнадійніший і перевірений AI-асистент із найбільшою екосистемою та активною розробкою", "✅ Ви працюєте у VS Code, JetBrains чи Visual Studio і хочете безшовну вбудовану інтеграцію", "✅ Ваша команда на GitHub і хоче AI прямо в PR, issues та код-рев''ю", "✅ Вам потрібен безкоштовний старт ($0/міс) і простий перехід на Pro за $10/міс із вибором моделей", "✅ Вам потрібні корпоративні функції: SSO, аудит-логи, IP-індемніті та політики керування"]', faq='[{"q": "Continue.dev усе ще незалежний продукт?", "a": "Ні. Continue був придбаний Cursor (Anysphere) приблизно в середині червня 2026 року, і окремий продукт згортається. Залишилися лише open-source розширення для IDE (VS Code та JetBrains) з версією v2.0.0 як фінальним релізом. Ви й далі можете використовувати ці open-source розширення для підключення власних LLM."}, {"q": "Continue.dev безкоштовний?", "a": "Open-source розширення для IDE безкоштовні. Підписки Continue немає — ви платите лише за API підключеної моделі (наприклад, Claude Opus 4.8 чи GPT-5.5) або взагалі нічого, якщо запускаєте локальні моделі через Ollama."}, {"q": "Скільки коштує GitHub Copilot?", "a": "У 2026 році GitHub Copilot — це мультимодельна платформа. Безкоштовний план Individual коштує $0/міс (близько 2 000 автодоповнень на місяць з обмеженим чатом і агентом та автоматичним вибором моделі). Pro коштує $10/міс з безлімітними автодоповненнями та вибором моделей, а перевірені студенти отримують Copilot безкоштовно."}, {"q": "Чи може Continue.dev використовувати локальні моделі?", "a": "Так. Open-source розширення підключаються до Ollama або LM Studio з локальними моделями (Llama, Mistral, Qwen та іншими) для повністю приватної офлайн-допомоги в розробці без витрат на API."}]'::jsonb WHERE slug='continue-dev-vs-github-copilot' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם רוצים את תוספי ה-IDE בקוד פתוח (VS Code, JetBrains) כדי לחבר כל LLM — Claude Opus 4.8, GPT-5.5 או מודלים מקומיים של Ollama — בלי נעילה לספק יחיד", "✅ הפרטיות חשובה לכם ואתם רוצים להריץ מודלים מקומיים כך שהקוד לעולם לא יוצא מהמחשב שלכם", "✅ אתם רוצים עוזר בשליטה מלאה שאתם מארחים בעצמכם, בלי דמי מנוי — משלמים רק על ה-API של המודל שאתם מחברים", "✅ אתם בונים תהליכי AI מותאמים אישית וגמישים ורוצים עוזר ניתן להרחבה שאתם מגדירים בעצמכם"]', choose_b='["✅ אתם רוצים את עוזר ה-AI האמין והבדוק ביותר עם האקוסיסטם הגדול ביותר ופיתוח פעיל", "✅ אתם משתמשים ב-VS Code, JetBrains או Visual Studio ורוצים אינטגרציה מובנית וחלקה ב-IDE", "✅ הצוות שלכם ב-GitHub ורוצה AI ישירות ב-PRs, issues וביקורות קוד", "✅ אתם צריכים התחלה חינמית ($0/חודש) ומסלול פשוט ל-Pro ב-$10/חודש עם בחירת מודלים", "✅ אתם צריכים תכונות ארגוניות: SSO, יומני ביקורת, שיפוי קניין רוחני ובקרות מדיניות"]', faq='[{"q": "האם Continue.dev עדיין מוצר עצמאי?", "a": "לא. Continue נרכשה על ידי Cursor (Anysphere) בערך באמצע יוני 2026, והמוצר העצמאי נסגר בהדרגה. מה שנותר הם תוספי ה-IDE בקוד פתוח ל-VS Code ול-JetBrains, כאשר v2.0.0 היא הגרסה הסופית. עדיין ניתן להשתמש בתוספים בקוד פתוח כדי לחבר LLM משלכם."}, {"q": "האם Continue.dev חינמי?", "a": "תוספי ה-IDE בקוד פתוח חינמיים. אין דמי מנוי של Continue — משלמים רק על ה-API של המודל שמחברים (למשל Claude Opus 4.8 או GPT-5.5), או כלום אם מריצים מודלים מקומיים דרך Ollama."}, {"q": "כמה עולה GitHub Copilot?", "a": "בשנת 2026 GitHub Copilot היא פלטפורמה רב-מודלית. תוכנית Individual Free עולה $0/חודש (כ-2,000 השלמות בחודש עם צ''אט וסוכן מוגבלים ובחירת מודל אוטומטית). Pro עולה $10/חודש עם השלמות ללא הגבלה ובחירת מודלים, וסטודנטים מאומתים מקבלים את Copilot בחינם."}, {"q": "האם Continue.dev יכול להשתמש במודלים מקומיים?", "a": "כן. התוספים בקוד פתוח מתחברים ל-Ollama או ל-LM Studio עם מודלים מקומיים (Llama, Mistral, Qwen ואחרים) לסיוע בכתיבת קוד פרטי לחלוטין, לא מקוון, וללא עלויות API."}]'::jsonb WHERE slug='continue-dev-vs-github-copilot' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous voulez les extensions IDE open source (VS Code, JetBrains) pour connecter n''importe quel LLM — Claude Opus 4.8, GPT-5.5 ou des modèles locaux Ollama — sans dépendre d''un seul fournisseur", "✅ Vous privilégiez la confidentialité et voulez exécuter des modèles locaux pour que votre code ne quitte jamais votre machine", "✅ Vous voulez un assistant auto-hébergé et entièrement sous votre contrôle, sans frais d''abonnement — vous ne payez que l''API du modèle que vous connectez", "✅ Vous créez des workflows d''IA personnalisés et modulables et voulez un assistant extensible que vous configurez vous-même"]', choose_b='["✅ Vous voulez l''assistant IA le plus fiable et le plus éprouvé, avec le plus grand écosystème et un développement actif", "✅ Vous utilisez VS Code, JetBrains ou Visual Studio et voulez une intégration IDE native et fluide", "✅ Votre équipe est sur GitHub et veut l''IA intégrée aux PR, issues et revues de code", "✅ Vous voulez un démarrage gratuit (0 $/mois) et un passage simple à Pro à 10 $/mois avec sélection de modèles", "✅ Vous avez besoin de fonctionnalités entreprise : SSO, journaux d''audit, indemnisation PI et contrôles de politique"]', faq='[{"q": "Continue.dev est-il encore un produit indépendant ?", "a": "Non. Continue a été racheté par Cursor (Anysphere) vers la mi-juin 2026, et le produit autonome est en cours d''arrêt. Ce qui reste, ce sont les extensions IDE open source pour VS Code et JetBrains, avec la v2.0.0 comme version finale. Vous pouvez toujours utiliser ces extensions open source pour connecter vos propres LLM."}, {"q": "Continue.dev est-il gratuit ?", "a": "Les extensions IDE open source sont gratuites. Il n''y a pas de frais d''abonnement Continue — vous ne payez que l''API du modèle que vous connectez (par exemple Claude Opus 4.8 ou GPT-5.5), ou rien du tout si vous exécutez des modèles locaux via Ollama."}, {"q": "Combien coûte GitHub Copilot ?", "a": "En 2026, GitHub Copilot est une plateforme multi-modèles. Le forfait Individual Free coûte 0 $/mois (environ 2 000 complétions par mois avec chat et agent limités et sélection automatique du modèle). Pro coûte 10 $/mois avec complétions illimitées et sélection de modèles, et les étudiants vérifiés obtiennent Copilot gratuitement."}, {"q": "Continue.dev peut-il utiliser des modèles locaux ?", "a": "Oui. Les extensions open source se connectent à Ollama ou LM Studio exécutant des modèles locaux (Llama, Mistral, Qwen et d''autres) pour une assistance au codage entièrement privée, hors ligne et sans coûts d''API."}]'::jsonb WHERE slug='continue-dev-vs-github-copilot' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você quer as extensões de IDE de código aberto (VS Code, JetBrains) para conectar qualquer LLM — Claude Opus 4.8, GPT-5.5 ou modelos locais do Ollama — sem ficar preso a um único provedor", "✅ Você prioriza a privacidade e quer rodar modelos locais para que seu código nunca saia da sua máquina", "✅ Você quer um assistente auto-hospedado e sob seu controle total, sem taxa de assinatura — você paga apenas pela API do modelo que conectar", "✅ Você cria fluxos de trabalho de IA personalizados e flexíveis e quer um assistente extensível que você mesmo configura"]', choose_b='["✅ Você quer o assistente de IA mais confiável e testado, com o maior ecossistema e desenvolvimento ativo", "✅ Você usa VS Code, JetBrains ou Visual Studio e quer uma integração nativa e fluida na IDE", "✅ Sua equipe está no GitHub e quer IA integrada a PRs, issues e revisões de código", "✅ Você quer começar de graça ($0/mês) e um caminho simples para o Pro a $10/mês com seleção de modelos", "✅ Você precisa de recursos empresariais: SSO, logs de auditoria, indenização de PI e controles de política"]', faq='[{"q": "O Continue.dev ainda é um produto independente?", "a": "Não. O Continue foi adquirido pelo Cursor (Anysphere) por volta de meados de junho de 2026, e o produto independente está sendo descontinuado. O que resta são as extensões de IDE de código aberto para VS Code e JetBrains, com a v2.0.0 como versão final. Você ainda pode usar essas extensões de código aberto para conectar seus próprios LLMs."}, {"q": "O Continue.dev é gratuito?", "a": "As extensões de IDE de código aberto são gratuitas. Não há taxa de assinatura do Continue — você paga apenas pela API do modelo que conectar (por exemplo, Claude Opus 4.8 ou GPT-5.5), ou nada se rodar modelos locais via Ollama."}, {"q": "Quanto custa o GitHub Copilot?", "a": "Em 2026, o GitHub Copilot é uma plataforma multimodelo. O plano Individual Free custa $0/mês (cerca de 2.000 conclusões por mês com chat e agente limitados e seleção automática de modelo). O Pro custa $10/mês com conclusões ilimitadas e seleção de modelos, e estudantes verificados recebem o Copilot gratuitamente."}, {"q": "O Continue.dev pode usar modelos locais?", "a": "Sim. As extensões de código aberto se conectam ao Ollama ou LM Studio rodando modelos locais (Llama, Mistral, Qwen e outros) para uma assistência de codificação totalmente privada, offline e sem custos de API."}]'::jsonb WHERE slug='continue-dev-vs-github-copilot' AND lang='pt';

-- autogpt-vs-manus
UPDATE comparisons SET choose_a='["✅ You want open-source autonomous AI you can self-host, modify, and fully control (MIT license, $0, bring your own LLM API keys)", "✅ You''re a developer building or experimenting with autonomous agent workflows and want a transparent, hackable platform", "✅ You want to customize the agent''s blocks, memory, and tool integrations, or run it on your own infrastructure", "✅ You''d rather use managed hosting when convenient — AutoGPT Pro ($50/mo, or $42.50/mo billed annually) and Max ($320/mo) run the platform for you"]', choose_b='["✅ You want a polished autonomous agent that completes complex tasks with minimal setup", "✅ You need an agent that browses the web, writes code, manages files, and executes multi-step plans on its own", "✅ You want results, not engineering — Manus handles the complexity so you can focus on the task", "✅ You prefer simple credit-based pricing: a free tier (300 daily refresh credits) and Pro plans from $20/mo"]', faq='[{"q": "What is AutoGPT?", "a": "AutoGPT was one of the first open-source autonomous AI agent projects (2023). It has since grown into the AutoGPT Platform (current release: autogpt-platform-beta-v0.6.65, June 2026), a block-based system for building and running autonomous agents. You can self-host it for free under the MIT license and bring your own LLM API keys, or use the managed Pro and Max tiers."}, {"q": "How much does AutoGPT cost?", "a": "Self-hosting is free (MIT license, $0) — you only pay for your own LLM API and compute. The managed cloud offers Pro at $50/mo ($42.50/mo billed annually, $510/yr) and Max at $320/mo."}, {"q": "What is Manus and what does it cost?", "a": "Manus is a general-purpose autonomous AI agent. The current family is Manus 1.6 — 1.6 Lite, 1.6, and the flagship 1.6 Max. Pricing is credit-based: a Free tier with 300 daily refresh credits, and Pro plans at $20/mo (4,000 credits), $40/mo (8,000 credits, 7-day trial), and $200/mo (40,000 credits). Team plans start at $20/seat/mo (2-seat minimum)."}, {"q": "What can Manus do that AutoGPT can''t?", "a": "Manus is a ready-to-use product with reliable web browsing and tool use, so you get task completion without building infrastructure. AutoGPT gives you an open, customizable platform to build agents yourself — more control and transparency, but more setup. Choose Manus for turnkey results; choose AutoGPT to own and shape the agent."}]'::jsonb WHERE slug='autogpt-vs-manus' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Нужен автономный ИИ с открытым кодом, который можно развернуть у себя, менять и полностью контролировать (лицензия MIT, $0, свои API-ключи к LLM)", "✅ Вы разработчик и создаёте или экспериментируете с автономными агентами, вам нужна прозрачная и гибкая платформа", "✅ Хотите настраивать блоки агента, память и интеграции инструментов или запускать всё на своей инфраструктуре", "✅ При желании удобнее платный хостинг — AutoGPT Pro ($50/мес или $42,50/мес при годовой оплате) и Max ($320/мес) берут платформу на себя"]', choose_b='["✅ Нужен готовый автономный агент, который решает сложные задачи с минимальной настройкой", "✅ Нужен агент, который сам ищет в интернете, пишет код, работает с файлами и выполняет многошаговые планы", "✅ Вам важен результат, а не инженерия — Manus берёт сложность на себя, вы сосредоточены на задаче", "✅ Предпочитаете простую оплату по кредитам: бесплатный тариф (300 обновляемых кредитов в день) и планы Pro от $20/мес"]', faq='[{"q": "Что такое AutoGPT?", "a": "AutoGPT — один из первых проектов автономных ИИ-агентов с открытым кодом (2023). С тех пор он вырос в платформу AutoGPT Platform (актуальная версия: autogpt-platform-beta-v0.6.65, июнь 2026) — блочную систему для создания и запуска автономных агентов. Её можно бесплатно развернуть у себя по лицензии MIT со своими API-ключами к LLM или использовать управляемые тарифы Pro и Max."}, {"q": "Сколько стоит AutoGPT?", "a": "Самостоятельное развёртывание бесплатно (лицензия MIT, $0) — вы платите только за свой LLM API и вычисления. Управляемое облако: Pro за $50/мес ($42,50/мес при годовой оплате, $510/год) и Max за $320/мес."}, {"q": "Что такое Manus и сколько он стоит?", "a": "Manus — универсальный автономный ИИ-агент. Текущее семейство — Manus 1.6: 1.6 Lite, 1.6 и флагман 1.6 Max. Оплата по кредитам: бесплатный тариф с 300 обновляемыми кредитами в день и планы Pro за $20/мес (4 000 кредитов), $40/мес (8 000 кредитов, пробный период 7 дней) и $200/мес (40 000 кредитов). Командные планы — от $20 за место в месяц (минимум 2 места)."}, {"q": "Что умеет Manus, чего не умеет AutoGPT?", "a": "Manus — готовый продукт с надёжным веб-браузингом и работой с инструментами, поэтому вы получаете результат без создания инфраструктуры. AutoGPT даёт открытую настраиваемую платформу, чтобы строить агентов самому — больше контроля и прозрачности, но и больше настройки. Выбирайте Manus ради результата «из коробки», AutoGPT — чтобы владеть агентом и формировать его под себя."}]'::jsonb WHERE slug='autogpt-vs-manus' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Quieres una IA autónoma de código abierto que puedas autoalojar, modificar y controlar por completo (licencia MIT, $0, tus propias claves API de LLM)", "✅ Eres desarrollador y construyes o experimentas con flujos de agentes autónomos y quieres una plataforma transparente y personalizable", "✅ Quieres personalizar los bloques del agente, la memoria y las integraciones de herramientas, o ejecutarlo en tu propia infraestructura", "✅ Prefieres un alojamiento gestionado cuando conviene — AutoGPT Pro ($50/mes o $42,50/mes con facturación anual) y Max ($320/mes) ejecutan la plataforma por ti"]', choose_b='["✅ Quieres un agente autónomo pulido que complete tareas complejas con una configuración mínima", "✅ Necesitas un agente que navegue por la web, escriba código, gestione archivos y ejecute planes de varios pasos por su cuenta", "✅ Quieres resultados, no ingeniería — Manus se encarga de la complejidad para que te centres en la tarea", "✅ Prefieres precios sencillos por créditos: un plan gratuito (300 créditos renovables al día) y planes Pro desde $20/mes"]', faq='[{"q": "¿Qué es AutoGPT?", "a": "AutoGPT fue uno de los primeros proyectos de agentes de IA autónomos de código abierto (2023). Desde entonces ha crecido hasta convertirse en AutoGPT Platform (versión actual: autogpt-platform-beta-v0.6.65, junio de 2026), un sistema por bloques para crear y ejecutar agentes autónomos. Puedes autoalojarlo gratis bajo licencia MIT con tus propias claves API de LLM, o usar los planes gestionados Pro y Max."}, {"q": "¿Cuánto cuesta AutoGPT?", "a": "El autoalojamiento es gratuito (licencia MIT, $0): solo pagas tu propia API de LLM y el cómputo. La nube gestionada ofrece Pro a $50/mes ($42,50/mes con facturación anual, $510/año) y Max a $320/mes."}, {"q": "¿Qué es Manus y cuánto cuesta?", "a": "Manus es un agente de IA autónomo de propósito general. La familia actual es Manus 1.6: 1.6 Lite, 1.6 y el buque insignia 1.6 Max. El precio es por créditos: un plan gratuito con 300 créditos renovables al día, y planes Pro de $20/mes (4.000 créditos), $40/mes (8.000 créditos, prueba de 7 días) y $200/mes (40.000 créditos). Los planes Team empiezan en $20 por asiento al mes (mínimo 2 asientos)."}, {"q": "¿Qué puede hacer Manus que AutoGPT no?", "a": "Manus es un producto listo para usar con navegación web y uso de herramientas fiables, así que obtienes tareas completadas sin construir infraestructura. AutoGPT te da una plataforma abierta y personalizable para construir agentes tú mismo: más control y transparencia, pero más configuración. Elige Manus por resultados llave en mano; elige AutoGPT para ser dueño del agente y moldearlo."}]'::jsonb WHERE slug='autogpt-vs-manus' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du willst eine quelloffene autonome KI, die du selbst hosten, anpassen und vollständig kontrollieren kannst (MIT-Lizenz, $0, eigene LLM-API-Schlüssel)", "✅ Du bist Entwickler, baust autonome Agenten-Workflows oder experimentierst damit und willst eine transparente, anpassbare Plattform", "✅ Du willst die Blöcke, den Speicher und die Tool-Integrationen des Agenten anpassen oder ihn auf eigener Infrastruktur betreiben", "✅ Bei Bedarf ist gehostetes Hosting bequemer — AutoGPT Pro ($50/Monat oder $42,50/Monat bei jährlicher Abrechnung) und Max ($320/Monat) betreiben die Plattform für dich"]', choose_b='["✅ Du willst einen ausgereiften autonomen Agenten, der komplexe Aufgaben mit minimaler Einrichtung erledigt", "✅ Du brauchst einen Agenten, der eigenständig im Web surft, Code schreibt, Dateien verwaltet und mehrstufige Pläne ausführt", "✅ Du willst Ergebnisse statt Technik — Manus übernimmt die Komplexität, damit du dich auf die Aufgabe konzentrieren kannst", "✅ Du bevorzugst einfache kreditbasierte Preise: einen kostenlosen Tarif (300 täglich erneuerte Credits) und Pro-Pläne ab $20/Monat"]', faq='[{"q": "Was ist AutoGPT?", "a": "AutoGPT war eines der ersten quelloffenen Projekte für autonome KI-Agenten (2023). Inzwischen ist daraus die AutoGPT Platform gewachsen (aktuelle Version: autogpt-platform-beta-v0.6.65, Juni 2026) – ein blockbasiertes System zum Erstellen und Ausführen autonomer Agenten. Du kannst sie unter der MIT-Lizenz kostenlos selbst hosten und eigene LLM-API-Schlüssel nutzen oder die verwalteten Pro- und Max-Tarife verwenden."}, {"q": "Was kostet AutoGPT?", "a": "Das Selbsthosting ist kostenlos (MIT-Lizenz, $0) – du zahlst nur für deine eigene LLM-API und Rechenleistung. Die verwaltete Cloud bietet Pro für $50/Monat ($42,50/Monat bei jährlicher Abrechnung, $510/Jahr) und Max für $320/Monat."}, {"q": "Was ist Manus und was kostet es?", "a": "Manus ist ein universeller autonomer KI-Agent. Die aktuelle Familie ist Manus 1.6: 1.6 Lite, 1.6 und das Flaggschiff 1.6 Max. Die Abrechnung erfolgt kreditbasiert: ein kostenloser Tarif mit 300 täglich erneuerten Credits sowie Pro-Pläne für $20/Monat (4.000 Credits), $40/Monat (8.000 Credits, 7-Tage-Test) und $200/Monat (40.000 Credits). Team-Pläne beginnen bei $20 pro Platz und Monat (mindestens 2 Plätze)."}, {"q": "Was kann Manus, was AutoGPT nicht kann?", "a": "Manus ist ein sofort einsatzbereites Produkt mit zuverlässigem Web-Browsing und Tool-Einsatz – du bekommst erledigte Aufgaben, ohne Infrastruktur aufzubauen. AutoGPT bietet dir eine offene, anpassbare Plattform, um Agenten selbst zu bauen: mehr Kontrolle und Transparenz, aber mehr Einrichtung. Wähle Manus für schlüsselfertige Ergebnisse; wähle AutoGPT, um den Agenten selbst zu besitzen und zu gestalten."}]'::jsonb WHERE slug='autogpt-vs-manus' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Потрібен автономний ШІ з відкритим кодом, який можна розгорнути у себе, змінювати й повністю контролювати (ліцензія MIT, $0, власні API-ключі до LLM)", "✅ Ви розробник і створюєте або експериментуєте з автономними агентами, вам потрібна прозора й гнучка платформа", "✅ Хочете налаштовувати блоки агента, памʼять та інтеграції інструментів або запускати все на власній інфраструктурі", "✅ За потреби зручніший керований хостинг — AutoGPT Pro ($50/міс або $42,50/міс за річної оплати) і Max ($320/міс) беруть платформу на себе"]', choose_b='["✅ Потрібен готовий автономний агент, який виконує складні завдання з мінімальним налаштуванням", "✅ Потрібен агент, який сам шукає в інтернеті, пише код, працює з файлами й виконує багатокрокові плани", "✅ Вам важливий результат, а не інженерія — Manus бере складність на себе, ви зосереджені на завданні", "✅ Надаєте перевагу простій оплаті за кредити: безкоштовний тариф (300 оновлюваних кредитів на день) і плани Pro від $20/міс"]', faq='[{"q": "Що таке AutoGPT?", "a": "AutoGPT — один із перших проєктів автономних ШІ-агентів з відкритим кодом (2023). Відтоді він виріс у платформу AutoGPT Platform (актуальна версія: autogpt-platform-beta-v0.6.65, червень 2026) — блокову систему для створення та запуску автономних агентів. Її можна безкоштовно розгорнути у себе за ліцензією MIT із власними API-ключами до LLM або скористатися керованими тарифами Pro та Max."}, {"q": "Скільки коштує AutoGPT?", "a": "Самостійне розгортання безкоштовне (ліцензія MIT, $0) — ви платите лише за власний LLM API та обчислення. Керована хмара: Pro за $50/міс ($42,50/міс за річної оплати, $510/рік) і Max за $320/міс."}, {"q": "Що таке Manus і скільки він коштує?", "a": "Manus — універсальний автономний ШІ-агент. Поточна лінійка — Manus 1.6: 1.6 Lite, 1.6 і флагман 1.6 Max. Оплата за кредити: безкоштовний тариф із 300 оновлюваними кредитами на день і плани Pro за $20/міс (4 000 кредитів), $40/міс (8 000 кредитів, пробний період 7 днів) та $200/міс (40 000 кредитів). Командні плани — від $20 за місце на місяць (мінімум 2 місця)."}, {"q": "Що вміє Manus, чого не вміє AutoGPT?", "a": "Manus — готовий продукт із надійним веб-браузингом і роботою з інструментами, тож ви отримуєте результат без побудови інфраструктури. AutoGPT дає відкриту налаштовувану платформу, щоб будувати агентів самостійно — більше контролю та прозорості, але й більше налаштування. Обирайте Manus заради результату «з коробки», AutoGPT — щоб володіти агентом і формувати його під себе."}]'::jsonb WHERE slug='autogpt-vs-manus' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם רוצים בינה מלאכותית אוטונומית בקוד פתוח שאפשר לארח בעצמכם, לשנות ולשלוט בה במלואה (רישיון MIT, $0, מפתחות API משלכם ל-LLM)", "✅ אתם מפתחים שבונים או מתנסים בזרימות עבודה של סוכנים אוטונומיים ורוצים פלטפורמה שקופה וניתנת להתאמה", "✅ אתם רוצים להתאים אישית את בלוקי הסוכן, הזיכרון ואינטגרציות הכלים, או להריץ אותו על התשתית שלכם", "✅ כשנוח לכם, אירוח מנוהל עדיף — AutoGPT Pro ($50 לחודש או $42.50 לחודש בחיוב שנתי) ו-Max ($320 לחודש) מריצים את הפלטפורמה בשבילכם"]', choose_b='["✅ אתם רוצים סוכן אוטונומי מלוטש שמשלים משימות מורכבות עם הגדרה מינימלית", "✅ אתם צריכים סוכן שגולש ברשת, כותב קוד, מנהל קבצים ומבצע תוכניות רב-שלביות בעצמו", "✅ אתם רוצים תוצאות, לא הנדסה — Manus מטפל במורכבות כדי שתתמקדו במשימה", "✅ אתם מעדיפים תמחור פשוט מבוסס קרדיטים: תוכנית חינם (300 קרדיטים מתחדשים ביום) ותוכניות Pro החל מ-$20 לחודש"]', faq='[{"q": "מה זה AutoGPT?", "a": "AutoGPT היה אחד מפרויקטי סוכני ה-AI האוטונומיים הראשונים בקוד פתוח (2023). מאז הוא גדל לכדי AutoGPT Platform (הגרסה הנוכחית: autogpt-platform-beta-v0.6.65, יוני 2026) — מערכת מבוססת בלוקים לבניית והרצת סוכנים אוטונומיים. אפשר לארח אותה בעצמכם בחינם תחת רישיון MIT עם מפתחות API משלכם ל-LLM, או להשתמש בתוכניות המנוהלות Pro ו-Max."}, {"q": "כמה עולה AutoGPT?", "a": "אירוח עצמי הוא חינם (רישיון MIT, $0) — אתם משלמים רק על ה-LLM API והמחשוב שלכם. הענן המנוהל מציע Pro ב-$50 לחודש ($42.50 לחודש בחיוב שנתי, $510 לשנה) ו-Max ב-$320 לחודש."}, {"q": "מה זה Manus וכמה זה עולה?", "a": "Manus הוא סוכן AI אוטונומי כללי. המשפחה הנוכחית היא Manus 1.6: 1.6 Lite, 1.6 והדגל 1.6 Max. התמחור מבוסס קרדיטים: תוכנית חינם עם 300 קרדיטים מתחדשים ביום, ותוכניות Pro ב-$20 לחודש (4,000 קרדיטים), $40 לחודש (8,000 קרדיטים, ניסיון 7 ימים) ו-$200 לחודש (40,000 קרדיטים). תוכניות צוות מתחילות מ-$20 למושב לחודש (מינימום 2 מושבים)."}, {"q": "מה Manus יכול לעשות ש-AutoGPT לא?", "a": "Manus הוא מוצר מוכן לשימוש עם גלישה ברשת ושימוש בכלים אמינים, כך שאתם מקבלים משימות שהושלמו בלי לבנות תשתית. AutoGPT מעניק לכם פלטפורמה פתוחה וניתנת להתאמה לבנות סוכנים בעצמכם — יותר שליטה ושקיפות, אך יותר הגדרה. בחרו ב-Manus לתוצאות מהקופסה; בחרו ב-AutoGPT כדי להחזיק בסוכן ולעצב אותו."}]'::jsonb WHERE slug='autogpt-vs-manus' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous voulez une IA autonome open source que vous pouvez auto-héberger, modifier et contrôler entièrement (licence MIT, 0 $, vos propres clés API LLM)", "✅ Vous êtes développeur et construisez ou expérimentez des workflows d''agents autonomes, et vous voulez une plateforme transparente et personnalisable", "✅ Vous voulez personnaliser les blocs de l''agent, la mémoire et les intégrations d''outils, ou l''exécuter sur votre propre infrastructure", "✅ Un hébergement géré vous convient parfois mieux — AutoGPT Pro (50 $/mois ou 42,50 $/mois en facturation annuelle) et Max (320 $/mois) exécutent la plateforme pour vous"]', choose_b='["✅ Vous voulez un agent autonome abouti qui accomplit des tâches complexes avec un minimum de configuration", "✅ Vous avez besoin d''un agent qui navigue sur le web, écrit du code, gère des fichiers et exécute des plans en plusieurs étapes de manière autonome", "✅ Vous voulez des résultats, pas de l''ingénierie — Manus gère la complexité pour que vous vous concentriez sur la tâche", "✅ Vous préférez une tarification simple à base de crédits : une offre gratuite (300 crédits renouvelés par jour) et des offres Pro à partir de 20 $/mois"]', faq='[{"q": "Qu''est-ce qu''AutoGPT ?", "a": "AutoGPT a été l''un des premiers projets d''agents IA autonomes open source (2023). Il est depuis devenu la plateforme AutoGPT Platform (version actuelle : autogpt-platform-beta-v0.6.65, juin 2026), un système à base de blocs pour créer et exécuter des agents autonomes. Vous pouvez l''auto-héberger gratuitement sous licence MIT avec vos propres clés API LLM, ou utiliser les offres gérées Pro et Max."}, {"q": "Combien coûte AutoGPT ?", "a": "L''auto-hébergement est gratuit (licence MIT, 0 $) : vous ne payez que votre propre API LLM et le calcul. Le cloud géré propose Pro à 50 $/mois (42,50 $/mois en facturation annuelle, 510 $/an) et Max à 320 $/mois."}, {"q": "Qu''est-ce que Manus et combien coûte-t-il ?", "a": "Manus est un agent IA autonome polyvalent. La famille actuelle est Manus 1.6 : 1.6 Lite, 1.6 et le fleuron 1.6 Max. La tarification est basée sur des crédits : une offre gratuite avec 300 crédits renouvelés par jour, et des offres Pro à 20 $/mois (4 000 crédits), 40 $/mois (8 000 crédits, essai de 7 jours) et 200 $/mois (40 000 crédits). Les offres Team démarrent à 20 $ par siège et par mois (minimum 2 sièges)."}, {"q": "Que peut faire Manus qu''AutoGPT ne peut pas ?", "a": "Manus est un produit prêt à l''emploi avec une navigation web et un usage d''outils fiables : vous obtenez des tâches accomplies sans construire d''infrastructure. AutoGPT vous offre une plateforme ouverte et personnalisable pour construire vos propres agents — plus de contrôle et de transparence, mais plus de configuration. Choisissez Manus pour des résultats clés en main ; choisissez AutoGPT pour posséder l''agent et le façonner."}]'::jsonb WHERE slug='autogpt-vs-manus' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você quer uma IA autônoma de código aberto que possa auto-hospedar, modificar e controlar por completo (licença MIT, $0, suas próprias chaves de API de LLM)", "✅ Você é desenvolvedor e cria ou experimenta fluxos de agentes autônomos e quer uma plataforma transparente e personalizável", "✅ Você quer personalizar os blocos do agente, a memória e as integrações de ferramentas, ou executá-lo na sua própria infraestrutura", "✅ Quando for conveniente, prefere hospedagem gerenciada — AutoGPT Pro ($50/mês ou $42,50/mês na cobrança anual) e Max ($320/mês) executam a plataforma para você"]', choose_b='["✅ Você quer um agente autônomo polido que conclui tarefas complexas com configuração mínima", "✅ Você precisa de um agente que navegue na web, escreva código, gerencie arquivos e execute planos de várias etapas sozinho", "✅ Você quer resultados, não engenharia — o Manus cuida da complexidade para que você foque na tarefa", "✅ Você prefere preços simples baseados em créditos: um plano gratuito (300 créditos renováveis por dia) e planos Pro a partir de $20/mês"]', faq='[{"q": "O que é o AutoGPT?", "a": "O AutoGPT foi um dos primeiros projetos de agentes de IA autônomos de código aberto (2023). Desde então, cresceu e se tornou a AutoGPT Platform (versão atual: autogpt-platform-beta-v0.6.65, junho de 2026), um sistema baseado em blocos para criar e executar agentes autônomos. Você pode auto-hospedá-la gratuitamente sob a licença MIT com suas próprias chaves de API de LLM, ou usar os planos gerenciados Pro e Max."}, {"q": "Quanto custa o AutoGPT?", "a": "A auto-hospedagem é gratuita (licença MIT, $0): você paga apenas pela sua própria API de LLM e computação. A nuvem gerenciada oferece Pro por $50/mês ($42,50/mês na cobrança anual, $510/ano) e Max por $320/mês."}, {"q": "O que é o Manus e quanto custa?", "a": "O Manus é um agente de IA autônomo de uso geral. A família atual é o Manus 1.6: 1.6 Lite, 1.6 e o carro-chefe 1.6 Max. O preço é baseado em créditos: um plano gratuito com 300 créditos renováveis por dia, e planos Pro a $20/mês (4.000 créditos), $40/mês (8.000 créditos, teste de 7 dias) e $200/mês (40.000 créditos). Os planos Team começam em $20 por assento ao mês (mínimo de 2 assentos)."}, {"q": "O que o Manus faz que o AutoGPT não faz?", "a": "O Manus é um produto pronto para usar, com navegação na web e uso de ferramentas confiáveis, então você obtém tarefas concluídas sem construir infraestrutura. O AutoGPT oferece uma plataforma aberta e personalizável para você mesmo construir agentes — mais controle e transparência, mas mais configuração. Escolha o Manus para resultados prontos; escolha o AutoGPT para ser dono do agente e moldá-lo."}]'::jsonb WHERE slug='autogpt-vs-manus' AND lang='pt';
